from cyclopts import App

app = App()


@app.command
def start():
    """Start the service."""
    print("Starting...")


@app.command
def stop():
    """Stop the service."""
    print("Stopping...")


@app.default
def status():
    """Show the current status (runs when no subcommand is given)."""
    print("Status: running")


if __name__ == "__main__":
